import Testing
@testable import TwelveStepKit

/// Golden vectors: messages hard-coded in the official editor (KMI_SysexMessages.c) whose CRCs were
/// generated by KMI's own encoder. Reproducing them byte-for-byte proves the framing port is exact.
struct KMIFramingTests {
    @Test func reproducesTetherOnExactly() {
        let packet = KMIPacket(pid: 0x14, packetType: 9, blocks: [[0x00, 0x04, 0x01]])
        #expect(KMIFraming.encode(packet) == TwelveStepMessages.tetherOn)
    }

    @Test func reproducesTetherOffExactly() {
        let packet = KMIPacket(pid: 0x14, packetType: 9, blocks: [[0x00, 0x04, 0x00]])
        #expect(KMIFraming.encode(packet) == TwelveStepMessages.tetherOff)
    }

    @Test func reproducesStandaloneOnExactly() {
        let packet = KMIPacket(pid: 0x14, packetType: 9, blocks: [[0x00, 0x03, 0x01]])
        #expect(KMIFraming.encode(packet) == TwelveStepMessages.standaloneOn)
    }

    @Test func reproducesBootloaderCommandExactly() {
        // Encoded only to prove the framing; the app never sends it.
        let packet = KMIPacket(pid: 0x14, packetType: 5)
        #expect(KMIFraming.encode(packet) == TwelveStepMessages.enterBootloader)
    }

    @Test func decodesGoldenVectors() throws {
        let tether = try KMIFraming.decode(TwelveStepMessages.tetherOn)
        #expect(tether.pid == 0x14)
        #expect(tether.packetType == 9)
        #expect(tether.blocks == [[0x00, 0x04, 0x01]])

        let bootloader = try KMIFraming.decode(TwelveStepMessages.enterBootloader)
        #expect(bootloader.packetType == 5)
        #expect(bootloader.blocks.isEmpty)
    }

    @Test func crcMatchesEmbeddedValues() {
        #expect(KMICRC.checksum([0x00, 0x09, 0x00, 0x07]) == 0x6AB6)
        #expect(KMICRC.checksum([0x00, 0x04, 0x01, 0x00, 0x00]) == 0xECCD)
    }

    @Test func crcUsesSignedCharSemantics() {
        // With an unsigned byte the result would differ for values >= 0x80.
        let signed = KMICRC.update(0xFFFF, 0x80)
        let temp = UInt16((0xFFFF >> 8) ^ 0x80)
        var unsigned = UInt16(0xFFFF) << 8
        var quick = temp ^ (temp >> 4)
        unsigned ^= quick; quick <<= 5; unsigned ^= quick; quick <<= 7; unsigned ^= quick
        #expect(signed != unsigned)
    }

    @Test func detectsCorruptedPayload() {
        var corrupted = TwelveStepMessages.tetherOn
        corrupted[21] ^= 0x01 // flip a bit in the data
        #expect(throws: KMIFramingError.self) { try KMIFraming.decode(corrupted) }
    }

    @Test(arguments: [0, 1, 6, 7, 8, 13, 14, 191, 270, 1000])
    func roundTripsArbitraryPayloads(length: Int) throws {
        var generator = SystemRandomNumberGenerator()
        let payload = (0..<length).map { _ in UInt8.random(in: 0...255, using: &generator) }
        let packet = KMIPacket(pid: 22, category: 1, type: 5, payload: length == 0 ? nil : payload)
        let decoded = try KMIFraming.decode(KMIFraming.encode(packet))
        #expect(decoded == packet)
    }

    @Test func roundTripsChainedBlocks() throws {
        let packet = KMIPacket(pid: 0x14, packetType: 9, blocks: [[0, 0, 1, 0, 0, 2], Array(repeating: 0xAB, count: 191), Array(repeating: 0x7F, count: 191)])
        #expect(try KMIFraming.decode(KMIFraming.encode(packet, headerPadding: 10)) == packet)
    }

    @Test func sevenBitRoundTrip() {
        let data: [UInt8] = (0...255).map(UInt8.init)
        let encoded = SevenBitCodec.encode(data)
        #expect(encoded.allSatisfy { $0 < 0x80 })
        #expect(Array(SevenBitCodec.decode(encoded).prefix(data.count)) == data)
    }

    @Test func cvCalibrationRequestHasExpectedShape() throws {
        let request = TwelveStepMessages.cvCalibrationRequest
        #expect(request.first == 0xF0 && request.last == 0xF7)
        #expect(Array(request[1...5]) == [0x00, 0x01, 0x5F, 0x00, 22])
        let decoded = try KMIFraming.decode(request)
        #expect(decoded.category == 1 && decoded.type == 4 && decoded.blocks.isEmpty)
    }
}
